    '.js', '.mjs', '.cjs', '.ts', '.tsx', '.jsx',
    '.py', '.rb', '.go', '.rs', '.java', '.kt',
    '.cs', '.cpp', '.c', '.h', '.hpp',
    '.swift', '.dart', '.scala', '.php',
    '.vue', '.svelte', '.css', '.scss',
    '.sql', '.graphql', '.proto', '.tf',
    '.lua', '.r', '.jl', '.ex', '.exs',
    '.sh', '.bash', '.zsh', '.ps1',
