  function daemonDir(cwd) {
    return path.join(cwd, '.context');
  }

  function pidFile(cwd) {
    return path.join(daemonDir(cwd), 'daemon.pid');
  }

  function logFile(cwd) {
    return path.join(daemonDir(cwd), 'daemon.log');
  }

