    if (!Array.isArray(ranked) || !Array.isArray(expected)) return Infinity;
    const expSet = new Set(expected.map((f) => normalizePath(f)));
    for (let i = 0; i < ranked.length; i++) {
      if (expSet.has(normalizePath(ranked[i]))) return i + 1;
    }
    return Infinity;
