  const MAX_ROWS = 200;
  const SKIP_DIR = new Set(['.git', 'node_modules', 'vendor', 'dist', 'build', 'target', '.venv', 'venv', '__pycache__']);
  const MIG_EXT = new Set(['.sql', '.rb', '.py', '.js', '.ts']);

